CREATE VIEW rc2 AS
 SELECT md.tablename,
    md.lookupattr,
    md.class AS rangetable
   FROM md
  WHERE ((md.inv)::text = 'true'::text)
UNION
 SELECT DISTINCT md1.tablename,
    md1.lookupattr,
    md2.class AS rangetable
   FROM md md1,
    nmj,
    md md2
  WHERE ((((((((((((md1.inv)::text = 'false'::text) AND ((md2.inv)::text = 'false'::text)) AND ((md1.isview)::text = 'false'::text)) AND ((md2.isview)::text = 'false'::text)) AND ((md1.class)::text <> (md1.tablename)::text)) AND ((md2.class)::text <> (md2.tablename)::text)) AND ((md1.tablename)::text = (nmj.tablename)::text)) AND ((md1.lookupattr)::text = (nmj.lookupattr)::text)) AND ((md2.tablename)::text = (nmj.tablename)::text)) AND ((md2.lookupattr)::text = (nmj.fkjoinattr)::text)) AND ((md2.class)::text <> 'ANY'::text));


--
-- TOC entry 860 (class 1259 OID 93925)
-- Name: rc3; Type: VIEW; Schema: mondial_wrls_mici_n_pac; Owner: -
--

CREATE VIEW rc3 AS
 SELECT md.tablename,
    md.lookupattr,
    md.class AS rangetable
   FROM md
  WHERE ((md.inv)::text = 'true'::text)
UNION
 SELECT DISTINCT nmj.tablename,
    nmj.fkjoinattr AS lookupattr,
    md1.tablename AS rangetable
   FROM md md1,
    md md2,
    nmj
  WHERE (((((((((((md1.class)::text = (md2.class)::text) AND ((md1.class)::text <> 'ANY'::text)) AND ((md1.inv)::text = 'false'::text)) AND ((md2.inv)::text = 'false'::text)) AND ((md1.isview)::text = 'false'::text)) AND ((md2.isview)::text = 'false'::text)) AND (NOT ((md1.tablename)::text IN ( SELECT nmtables.tablename
           FROM nmtables)))) AND ((md2.tablename)::text IN ( SELECT nmtables.tablename
           FROM nmtables))) AND ((nmj.tablename)::text = (md2.tablename)::text)) AND ((nmj.lookupattr)::text = (md2.lookupattr)::text));


